package com.bank.flink.ct;

import java.util.List;
import java.util.Map;

// A parsed CREATE TABLE: schema, WITH options, optional watermark + primary key.
class TableDefinition {
    private final String name;
    private final List<String> columns;
    private final Map<String, String> options;  // the WITH (...) clause
    private final String watermarkColumn;        // null if none
    private final long watermarkDelayMillis;
    private final String primaryKey;             // null if none

    TableDefinition(String name, List<String> columns, Map<String, String> options,
                    String watermarkColumn, long watermarkDelayMillis, String primaryKey) {
        this.name = name;
        this.columns = columns;
        this.options = options;
        this.watermarkColumn = watermarkColumn;
        this.watermarkDelayMillis = watermarkDelayMillis;
        this.primaryKey = primaryKey;
    }

    String getName() { return name; }
    String connector() { return options.get("connector"); }
    String format() { return options.getOrDefault("format", "n/a"); }
    String option(String k) { return options.get(k); }
    boolean hasWatermark() { return watermarkColumn != null; }
    long watermarkDelayMillis() { return watermarkDelayMillis; }
    String primaryKey() { return primaryKey; }
    List<String> getColumns() { return columns; }
}
