package com.bank.flink.ct;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Catalog analogue: holds declared tables by name.
class TableRegistry {
    private static final Logger log = Logger.getLogger(TableRegistry.class.getName());

    private final Map<String, TableDefinition> tables = new HashMap<>();

    void createTable(TableDefinition def) {
        tables.put(def.getName(), def);
        log.info(() -> "CREATE TABLE " + def.getName() + " connector=" + def.connector()
                + " format=" + def.format()
                + (def.hasWatermark() ? " watermark(delay=" + def.watermarkDelayMillis() + "ms)" : "")
                + (def.primaryKey() != null ? " PK=" + def.primaryKey() : ""));
    }

    TableDefinition get(String name) { return tables.get(name); }
}
