package com.bank.flink.ct;

import java.util.logging.Logger;

// Uses a SOURCE table definition: decodes per its format and emits a watermark
// per the declared WATERMARK formula (maxEventTime - delay).
class SourceReader {
    private static final Logger log = Logger.getLogger(SourceReader.class.getName());

    private final TableDefinition def;
    private long maxEventTime = Long.MIN_VALUE;

    SourceReader(TableDefinition def) {
        this.def = def;
        if (!"kafka".equals(def.connector())) {
            log.warning(() -> def.getName() + " is not a kafka source in this demo");
        }
    }

    // Decode a raw JSON-ish record (demo: already parsed fields) and advance watermark.
    void read(String accountId, String amount, long eventTimeMillis) {
        // format=json would parse bytes here; we take parsed fields for the demo.
        if (eventTimeMillis > maxEventTime) maxEventTime = eventTimeMillis;
        long watermark = def.hasWatermark() ? maxEventTime - def.watermarkDelayMillis() : Long.MIN_VALUE;
        log.info(() -> "SOURCE[" + def.getName() + "/" + def.format() + "] row account="
                + accountId + " amount=" + amount + " eventTime=" + eventTimeMillis
                + " -> watermark=" + watermark);
    }
}
