package com.bank.flink.ct;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// Uses a SINK table definition: upserts rows by the declared PRIMARY KEY.
class SinkWriter {
    private static final Logger log = Logger.getLogger(SinkWriter.class.getName());

    private final TableDefinition def;
    private final Map<String, BigDecimal> table = new LinkedHashMap<>();

    SinkWriter(TableDefinition def) {
        this.def = def;
        if (def.primaryKey() == null) {
            log.warning(() -> def.getName() + " has no PRIMARY KEY; cannot upsert");
        }
    }

    void write(String accountId, BigDecimal total) {
        boolean existed = table.containsKey(accountId);
        table.put(accountId, total); // upsert by primary key
        log.info(() -> "SINK[" + def.getName() + "/" + def.connector() + "] "
                + (existed ? "UPDATE" : "INSERT") + " " + def.primaryKey() + "=" + accountId
                + " total=" + total);
    }

    Map<String, BigDecimal> snapshot() { return table; }
}
