package com.bank.flink.ct;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: declare a kafka/json source with watermark and a jdbc sink
// with a primary key, then read with watermarks and write with upserts.
public class CreateTableDemo {
    private static final Logger log = Logger.getLogger(CreateTableDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new CtLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TableRegistry registry = new TableRegistry();

        // CREATE TABLE transactions ... WITH ('connector'='kafka','format'='json') + WATERMARK
        TableDefinition source = new TableDefinition(
                "transactions",
                List.of("account_id", "amount", "event_time"),
                Map.of("connector", "kafka", "topic", "nbi.transactions",
                        "scan.startup.mode", "latest-offset", "format", "json"),
                "event_time", 5_000L, null);
        registry.createTable(source);

        // CREATE TABLE account_totals ... WITH ('connector'='jdbc') + PRIMARY KEY
        TableDefinition sink = new TableDefinition(
                "account_totals",
                List.of("account_id", "total"),
                Map.of("connector", "jdbc", "url", "jdbc:postgresql://db:5432/reporting",
                        "table-name", "account_totals"),
                null, 0L, "account_id");
        registry.createTable(sink);

        // Read transactions (source) showing watermark advance.
        SourceReader reader = new SourceReader(registry.get("transactions"));
        reader.read("SAV2001", "1000", 10_000);
        reader.read("CUR3001", "500", 12_000);
        reader.read("SAV2001", "250", 11_000);

        // Write aggregates (sink) showing upsert by primary key.
        SinkWriter writer = new SinkWriter(registry.get("account_totals"));
        writer.write("SAV2001", new BigDecimal("1250"));
        writer.write("CUR3001", new BigDecimal("500"));
        writer.write("SAV2001", new BigDecimal("1250")); // same key -> UPDATE
        log.info(() -> "Final sink table = " + writer.snapshot());
    }
}

// ─── Would be in CtLogFormatter.java in a real project ───
class CtLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
